import {goodsFor} from './creations.js';
import {PRINT_MODES,SHOP,printers,specFor,STATUS} from './model.js';
import {nextStudioProduct,studioGoal,estimateElectricity} from './product-lab.js';
import {MACHINE_SOURCES,SOURCE_DATE} from './machines.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),euro=n=>n.toLocaleString('fr-FR',{style:'currency',currency:'EUR'});
export const PILOT_TASKS=[['autoCraft','Fabriquer du stock pendant les temps creux','Respecte les cibles définies dans Créations, sans utiliser le filament réservé aux clients.'],['autoAccept','Confirmer les commandes réalisables','Plateau, qualité, charge de travail, stock et réserve sont vérifiés.'],['autoRestock','Réapprovisionner les couleurs nécessaires','Les bobines manquantes sont regroupées, avec un seul port.'],['autoShip','Expédier les colis prêts','Après finition et emballage, dans tes horaires de présence.'],['autoService','Entretenir et réparer les machines','Pièces commandées si besoin ; interventions sur ton temps disponible.'],['autoQuality','Adapter la qualité au besoin du client','Le profil soigné prend davantage de temps.'],['autoWebsite','Créer ma boutique quand l’offre est validée','Après 8 livraisons : 0 € de création, 8 h de travail.']];
export const idleIsOn=s=>s.settings.autoAccept&&s.settings.autoRestock&&s.settings.autoShip;
export function idleBar(s){const count=PILOT_TASKS.filter(([k])=>s.settings[k]).length;return `<button class="idle-main ${idleIsOn(s)?'enabled':''}" data-action="idle-preset" aria-label="${idleIsOn(s)?'Désactiver le pilotage idle':'Activer le pilotage idle'}"><i></i><span>${idleIsOn(s)?'Atelier autonome':'Activer l’idle'}</span></button><label>Temps creux<select data-idle-mode aria-label="Activité pendant les temps creux"><option value="none" ${s.studio.idleMode==='none'?'selected':''}>Temps libre</option><option value="research" ${s.studio.idleMode==='research'?'selected':''}>Chercher des modèles</option><option value="design" ${s.studio.idleMode==='design'?'selected':''}>Créer mes produits</option></select></label><button data-action="creations-panel" class="creations-access" aria-label="Créer, fabriquer et vendre mes objets">✦ <span>Créations</span><b>${goodsFor(s)}</b></button><button data-action="pilot-panel" class="idle-instructions">☑ <span>Consignes</span><b>${count}</b></button>`;}
export function pilotPanel(s){const pending=s.orders.find(o=>o.id===s.studio.pending),mode=s.studio.idleMode,next=mode==='none'?null:nextStudioProduct(s),progress=mode==='none'?0:s.studio.progress[mode],goal=mode==='none'?1:studioGoal(mode,next);return `<header><div><span class="eyebrow">TU DONNES LE CAP</span><h2>Les consignes de l’atelier</h2></div><button data-action="pilot-panel" aria-label="Fermer les consignes">×</button></header><div class="pilot-content"><div class="pilot-note"><b>Un rythme tranquille, pas une journée en une minute.</b><p>Le mode recommandé utilise ×240 en journée et ×480 pendant les absences : environ 4 à 5 minutes par jour simulé. Tu gardes tous les boutons de vitesse.</p></div><label class="idle-downtime">Pendant les temps creux<select data-idle-mode><option value="none" ${mode==='none'?'selected':''}>Temps libre</option><option value="research" ${mode==='research'?'selected':''}>Chercher des modèles</option><option value="design" ${mode==='design'?'selected':''}>Créer mes produits</option></select></label><section class="pilot-tasks">${PILOT_TASKS.map(([k,title,note])=>`<label><span><b>${title}</b><small>${note}</small></span><input type="checkbox" data-setting="${k}" ${s.settings[k]?'checked':''}></label>`).join('')}</section><section class="pilot-channels"><h3>Où proposer mon travail ?</h3>${[['useEtsy','Etsy','Tes créations originales et personnalisations.'],['useLocal','Clients directs','Fichiers clients, réparations, pros et retrait sur place.'],['useSite','Ma boutique','Active une fois créée : pas d’abonnement d’hébergement simulé.']].map(([k,title,note])=>`<label><input type="checkbox" data-setting="${k}" ${s.settings[k]?'checked':''}><span><b>${title}</b><small>${note}</small></span></label>`).join('')}</section><section class="studio-status"><span class="eyebrow">LES IDÉES PRENNENT FORME</span><h3>${pending?'Un prototype à valider':mode==='design'?'Mon prochain produit':mode==='research'?'La recherche de modèles':'Choisir les temps creux'}</h3>${pending?`<p><b>${esc(pending.prototypeMeta.name)}</b><br>${STATUS[pending.status]} · ${pending.grams} g pour le prototype, puis contrôle et photos.</p>`:next?`<p>${esc(next.name)}<small>${mode==='research'?'Autorisation commerciale simulée ; vente en direct et sur ta boutique. Les modèles tiers ne sont pas envoyés sur Etsy.':'Une création originale à vendre sur les canaux que tu choisis.'}</small></p><div class="studio-progress"><i style="width:${progress/goal*100}%"></i></div><span>${Math.round(progress)} / ${goal} min de travail · priorité aux commandes clients.</span>`:mode==='none'?'<p>Choisis une activité dans la barre sous l’atelier. Le travail attend ta présence et respecte le télétravail.</p>':'<p>Les projets de cette série sont tous validés. Le catalogue reste volontairement limité.</p>'}<button class="button secondary small" data-action="creations-panel">Choisir un objet à créer et vendre</button><p class="studio-footnote">Chercher un modèle ne donne aucun revenu : il faut vérifier les droits, réussir un prototype et trouver des acheteurs.</p></section>${s.studio.products.length?`<section class="studio-library"><h3>Mes produits validés · ${s.studio.products.length}</h3>${s.studio.products.map(p=>`<div><span>✦</span><b>${esc(p.name)}<small>${p.origin==='original'?'Création originale · Etsy possible':'Licence commerciale simulée · hors Etsy'}</small></b><em>${euro(p.price)}</em></div>`).join('')}</section>`:''}</div>`;}
export function projectForm(s){const next=nextStudioProduct(s,'design');return `<form id="product-project" class="product-project"><p class="modal-lead">Conçois un produit original dans la simulation. Il faut ${(studioGoal('design',next)/60).toLocaleString('fr-FR',{maximumFractionDigits:2})} h de conception, puis imprimer un prototype de ${next?.prototypeGrams||45} g, le contrôler et le photographier. Les commandes passent en premier.</p>${next?`<label>Base du prochain projet<input value="${esc(next.name)}" disabled></label><label>Nom de ma création<input name="name" maxlength="48" value="${esc(s.studio.draft.name||next.name)}" required></label><label>Prix de vente envisagé<span><input type="number" name="price" min="10" max="120" step="1" value="${s.studio.draft.price||next.price}" required> €</span></label><small>Ce prix ne garantit ni les ventes, ni la rentabilité. La matière, la fabrication, ton temps et les frais restent comptés.</small><div class="modal-actions"><button type="submit" class="button primary" ${s.studio.pending?'disabled':''}>Préparer ce projet</button></div>`:'<p>Tes créations originales de cette série sont déjà validées. Produis des exemplaires dans « Créations ».</p>'}</form>`;}
export function machineModes(m){const spec=specFor(m);return `<section class="machine-profiles"><h3>Le réglage d’impression</h3><div>${Object.entries(PRINT_MODES).map(([id,v])=>`<button data-action="print-mode" data-id="${m.id}" data-mode="${id}" aria-pressed="${(m.printMode||'standard')===id}" ${m.job?'disabled':''}><b>${v.name}</b><small>${v.layer.toLocaleString('fr-FR')} mm</small></button>`).join('')}</div><p>${spec.volume.join(' × ')} mm de volume utile · ${Math.round(spec.power*1000)} W moyens estimés. Les profils modifient le temps, le risque de raté et la finition ; ces effets sont des hypothèses de jeu.</p></section>`;}
export function compareMachines(){return `<p class="modal-lead">Des modèles réels, avec des prix de référence repérés dans les catalogues constructeurs le ${SOURCE_DATE}. Les promotions, la TVA de destination et la livraison peuvent changer le montant au panier. Le meuble à 45 € est une estimation du jeu.</p><div class="machine-comparison">${SHOP.filter(m=>m.kind==='printer').map(m=>`<article><span>${m.modelEnclosed?'CoreXY fermée':'Machine ouverte'}</span><h3>${esc(m.name)}</h3><strong>${euro(m.price)}</strong><p>${euro(m.machinePrice)} imprimante + ${euro(m.standPrice)} meuble</p><dl><div><dt>Volume utile</dt><dd>${m.volume.join(' × ')} mm</dd></div><div><dt>Vitesse maximale annoncée</dt><dd>${m.maxTravel?m.maxTravel+' mm/s':'Non utilisée pour le calcul'}</dd></div><div><dt>Temps d’un même travail, modèle</dt><dd>×${m.speed.toLocaleString('fr-FR')}</dd></div><div><dt>Consommation moyenne, modèle</dt><dd>${Math.round(m.power*1000)} W</dd></div></dl><a href="${m.source}" target="_blank" rel="noopener">Catalogue constructeur ↗</a></article>`).join('')}</div><p class="energy-footnote">Les volumes et les modèles sont issus des constructeurs. Les temps de fabrication, consommations moyennes et probabilités de raté sont des estimations de simulation : 500 mm/s en déplacement ne signifie pas 500 mm/s pendant toute une impression. Les anciennes machines conservent leurs performances et leur valeur d’achat.</p>`;}
export function energyProjection(s){const e=estimateElectricity(s);return `<div class="energy-projection"><b>Si le rythme actuel se poursuit</b><strong>≈ ${euro(e.monthEstimate)} / 30 jours</strong><small>Projection à partir de l’usage depuis le début et du tarif actuel. Ce n’est pas une nouvelle facture.</small></div>`;}
